package org.transittr;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;
import android.location.*;import android.os.*;import android.text.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;
import java.util.*;import java.util.concurrent.*;

/** Catalogue inside the main application shell; native recycled rows on API 8+. */
public final class CatalogScreen {
 public interface Navigation {void track(CatalogStore.Item item);void point(CatalogStore.Item item);void rail(String code);void route(CatalogStore.Item item);}
 public static final class State {public String query="";public int mode;public boolean nearby;public double lat,lon;}
 private ThemeColors palette;private int INK=0xff141414,MUTED=0xff606460,BLUE=0xff1d5fbf,GROUND=0xfff4f3f1;
 private final Activity activity;private final int city;private final Typeface font;private final boolean compact;private final State state;private final Navigation navigation;
 private final CatalogStore store;private final Handler main=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final ArrayList<CatalogStore.Item> items=new ArrayList<CatalogStore.Item>();private final TextView[] tabs=new TextView[3];private final View[] rules=new View[3];
 private final TextView stats,range,empty;private final EditText search;private final ListView list;private final Rows adapter;
 private volatile boolean closed;private volatile int generation;private boolean loading;private int total;private Dialog detailDialog;private LocationManager locationManager;private LocationListener locationListener;
 public CatalogScreen(final Activity activity,LinearLayout body,final int city,Typeface font,boolean compact,final State state,Navigation navigation){
  this.activity=activity;palette=ThemeColors.of(activity);INK=palette.ink;MUTED=palette.muted;BLUE=palette.blue;GROUND=palette.ground;this.city=city;this.font=font;this.compact=compact;this.state=state;this.navigation=navigation;store=new CatalogStore(activity);
  LinearLayout top=new LinearLayout(activity);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(20),0,dp(16),0);body.addView(top,new LinearLayout.LayoutParams(-1,dp(44)));
  top.addView(text("Katalog",24,INK),new LinearLayout.LayoutParams(0,-2,1));top.addView(button("Yakınımda",false,new View.OnClickListener(){public void onClick(View v){nearMenu();}}),new LinearLayout.LayoutParams(dp(108),dp(44)));
  stats=text("Çevrimdışı hat ve duraklar",12,MUTED);stats.setPadding(dp(20),dp(3),dp(16),dp(8));body.addView(stats);
  TextView widgetLink=text("Durak + hat favorileri →",13,INK);widgetLink.setPadding(dp(20),0,dp(16),0);widgetLink.setGravity(Gravity.CENTER_VERTICAL);body.addView(widgetLink,new LinearLayout.LayoutParams(-1,dp(40)));widgetLink.setOnClickListener(new View.OnClickListener(){public void onClick(View v){activity.startActivity(new Intent(activity,WidgetSetupActivity.class).putExtra("city",city));}});
  LinearLayout find=new LinearLayout(activity);find.setPadding(dp(16),0,dp(16),0);body.addView(find,new LinearLayout.LayoutParams(-1,dp(44)));
  search=new EditText(activity);search.setSingleLine(true);search.setTextSize(14);search.setTextColor(INK);search.setHintTextColor(MUTED);search.setHint("Hat kodu, durak adı veya numarası");search.setContentDescription("Katalogda hat veya durak ara");if(font!=null)search.setTypeface(font);search.setPadding(dp(12),0,dp(12),0);search.setBackgroundDrawable(shape(palette.surface,palette.border));search.setText(state.query);find.addView(search,new LinearLayout.LayoutParams(-1,-1));
  LinearLayout filters=new LinearLayout(activity);filters.setPadding(dp(16),dp(6),dp(16),0);body.addView(filters,new LinearLayout.LayoutParams(-1,dp(50)));
  String[] labels={"Hatlar","Duraklar","Kaydedilenler"};
  for(int i=0;i<3;i++){final int mode=i;FrameLayout cell=new FrameLayout(activity);filters.addView(cell,new LinearLayout.LayoutParams(0,-1,1));TextView label=text(labels[i],13,MUTED);label.setGravity(Gravity.CENTER);cell.addView(label,new FrameLayout.LayoutParams(-1,-1));View line=new View(activity);line.setBackgroundColor(INK);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,dp(2),Gravity.BOTTOM);cell.addView(line,lp);tabs[i]=label;rules[i]=line;cell.setOnClickListener(new View.OnClickListener(){public void onClick(View v){state.mode=mode;state.nearby=false;load(true);}});}
  range=text("",12,MUTED);range.setPadding(dp(20),dp(6),dp(20),dp(7));body.addView(range);
  FrameLayout results=new FrameLayout(activity);results.setBackgroundColor(palette.surface);body.addView(results,new LinearLayout.LayoutParams(-1,0,1));
  list=new ListView(activity);list.setCacheColorHint(palette.surface);list.setDivider(new ColorDrawable(palette.rule));list.setDividerHeight(dp(1));list.setPadding(dp(4),0,dp(4),0);adapter=new Rows(items);list.setAdapter(adapter);results.addView(list,new FrameLayout.LayoutParams(-1,-1));
  empty=text("Katalog hazırlanıyor…",14,MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(24),dp(20),dp(24),dp(20));results.addView(empty,new FrameLayout.LayoutParams(-1,-1));list.setEmptyView(empty);
  list.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> parent,View view,int position,long id){CatalogStore.Item item=items.get(position);if(item.kind==0)CatalogScreen.this.navigation.route(item);else detail(item);}});
  list.setOnItemLongClickListener(new AdapterView.OnItemLongClickListener(){public boolean onItemLongClick(AdapterView<?> parent,View view,int position,long id){toggle(items.get(position));return true;}});
  list.setOnScrollListener(new AbsListView.OnScrollListener(){public void onScrollStateChanged(AbsListView view,int state){}public void onScroll(AbsListView view,int first,int visible,int count){if(!loading&&!state.nearby&&count>0&&first+visible>=count-3&&items.size()<total)load(false);}});
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){state.query=s.toString();state.nearby=false;main.removeCallbacks(filter);main.postDelayed(filter,180);}public void afterTextChanged(Editable s){}});
  load(true);
 }
 private int dp(float v){return(int)(v*activity.getResources().getDisplayMetrics().density+.5f);}
 private TextView text(String value,int size,int color){TextView t=new TextView(activity);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(font!=null)t.setTypeface(font);return t;}
 private GradientDrawable shape(int fill,int border){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(6));if(border!=0)d.setStroke(dp(1),border);return d;}
 private Button button(String title,boolean primary,View.OnClickListener action){Button b=new Button(activity);b.setText(title);b.setTextSize(13);b.setTextColor(primary?palette.surface:INK);if(font!=null)b.setTypeface(font);b.setPadding(dp(10),0,dp(10),0);b.setMinHeight(dp(44));b.setMinimumHeight(dp(44));b.setMinWidth(0);b.setMinimumWidth(0);StateListDrawable states=new StateListDrawable();states.addState(new int[]{android.R.attr.state_pressed},shape(primary?(palette.dark?0xffd2dbd2:0xff363636):palette.input,0));states.addState(new int[]{},shape(primary?INK:palette.surface,primary?0:palette.border));b.setBackgroundDrawable(states);b.setOnClickListener(action);return b;}
 private final Runnable filter=new Runnable(){public void run(){load(true);}};
 private void load(final boolean reset){
  if(closed||(!reset&&loading))return;final int ticket=++generation,offset=reset?0:items.size(),mode=state.mode;final String query=state.query;final boolean nearby=state.nearby;final double lat=state.lat,lon=state.lon;
  loading=true;for(int i=0;i<tabs.length;i++){tabs[i].setTextColor(i==mode?INK:MUTED);rules[i].setVisibility(i==mode?View.VISIBLE:View.INVISIBLE);}
  if(reset){items.clear();adapter.notifyDataSetChanged();empty.setText("Katalog aranıyor…");list.setSelection(0);}range.setText(offset==0?"Aranıyor…":items.size()+" kayıt · devamı yükleniyor…");
  worker.execute(new Runnable(){public void run(){if(closed||ticket!=generation)return;try{final CatalogStore.Page page=nearby?store.nearby(city,lat,lon):store.page(city,mode,query,offset);main.post(new Runnable(){public void run(){if(closed||ticket!=generation)return;loading=false;total=page.total;items.addAll(page.items);adapter.notifyDataSetChanged();stats.setText(page.routes+" hat/yön · "+page.stops+" durak · Çevrimdışı");range.setText(nearby?page.total+" yakın durak · 2 km · kuş uçuşu":items.isEmpty()?"0 sonuç":items.size()+" / "+total+" kayıt");empty.setText(nearby?"Bu bölgede koordinatlı katalog kaydı yok.":mode==2?"Henüz kaydedilmiş bir hat veya durak yok.\nYıldız simgesine dokunarak kaydet.":"Sonuç bulunamadı.\nBaşka bir hat kodu veya durak adı dene.");}});}catch(Exception e){main.post(new Runnable(){public void run(){if(closed||ticket!=generation)return;loading=false;range.setText("Katalog açılamadı");empty.setText("Yerel katalog okunamadı. Sekmeyi yeniden açmayı dene.");}});}}});
 }
 private void toggle(CatalogStore.Item item){store.toggle(item);if(state.mode==2)load(true);else adapter.notifyDataSetChanged();}
 private final class Holder {TextView code,name,sub;ImageView star;}
 private final class Rows extends BaseAdapter {
  private final ArrayList<CatalogStore.Item> data;Rows(ArrayList<CatalogStore.Item> data){this.data=data;}
  public int getCount(){return data.size();}public Object getItem(int position){return data.get(position);}public long getItemId(int position){return data.get(position).id;}
  public View getView(int position,View reuse,ViewGroup parent){Holder h;LinearLayout row;if(reuse instanceof LinearLayout){row=(LinearLayout)reuse;h=(Holder)row.getTag();}else{row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(8),dp(4),dp(8));row.setMinimumHeight(dp(76));h=new Holder();h.code=text("",16,BLUE);h.code.setMaxLines(1);h.code.setEllipsize(TextUtils.TruncateAt.END);row.addView(h.code,new LinearLayout.LayoutParams(dp(62),-2));LinearLayout words=new LinearLayout(activity);words.setOrientation(1);h.name=text("",14,INK);h.name.setMaxLines(2);h.name.setEllipsize(TextUtils.TruncateAt.END);words.addView(h.name);h.sub=text("",12,MUTED);h.sub.setPadding(0,dp(3),0,0);words.addView(h.sub);row.addView(words,new LinearLayout.LayoutParams(0,-2,1));h.star=new ImageView(activity);h.star.setPadding(dp(10),dp(10),dp(10),dp(10));h.star.setFocusable(false);row.addView(h.star,new LinearLayout.LayoutParams(dp(44),dp(44)));row.setTag(h);}
   final CatalogStore.Item item=data.get(position);h.code.setText(item.code);h.name.setText(item.name);h.sub.setText(item.distance>=0?(int)item.distance+" m · Durak":item.kind==0?item.type:item.hasPosition()?"Durak":"Durak · konum verisi yok");h.star.setImageDrawable(new Star(store.saved(item)));h.star.setContentDescription(store.saved(item)?"Kaydı kaldır":"Kaydet");h.star.setOnClickListener(new View.OnClickListener(){public void onClick(View v){toggle(item);}});return row;}
 }
 private final class Star extends Drawable {private final Paint paint=new Paint(3);private final Path path=new Path();private final boolean filled;Star(boolean filled){this.filled=filled;for(int i=0;i<10;i++){double a=-Math.PI/2+i*Math.PI/5;float r=i%2==0?10:4.5f,x=12+(float)Math.cos(a)*r,y=12+(float)Math.sin(a)*r;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}path.close();}public void draw(Canvas c){Rect b=getBounds();int save=c.save();c.translate(b.left,b.top);c.scale(b.width()/24f,b.height()/24f);paint.setColor(filled?BLUE:MUTED);paint.setStyle(filled?Paint.Style.FILL:Paint.Style.STROKE);paint.setStrokeWidth(1.5f);c.drawPath(path,paint);c.restoreToCount(save);}public int getIntrinsicWidth(){return dp(24);}public int getIntrinsicHeight(){return dp(24);}public void setAlpha(int value){paint.setAlpha(value);}public void setColorFilter(ColorFilter filter){paint.setColorFilter(filter);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 private Dialog dialog(String title){Dialog d=new Dialog(activity);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setPadding(dp(20),dp(18),dp(20),dp(16));box.setBackgroundDrawable(shape(palette.surface,0));TextView heading=text(title,20,INK);heading.setMaxLines(3);box.addView(heading);LinearLayout content=new LinearLayout(activity);content.setId(7301);content.setOrientation(1);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(14);box.addView(content,cp);d.setContentView(box);if(d.getWindow()!=null)d.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));return d;}
 private void show(Dialog d){d.show();if(d.getWindow()!=null)d.getWindow().setLayout(Math.min(activity.getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),-2);}
 private boolean liveStop(CatalogStore.Item item){return item.kind==1&&(city==0&&item.code.matches("[0-9]{5}")||city==1&&item.code.matches("[0-9]{5,8}")||city==6&&item.code.matches("[0-9]{1,8}"));}
 private String railCode(CatalogStore.Item item){if(item.kind!=0)return "";String base=item.code.split("_")[0];if(city==0&&base.matches("[MA][0-9]-[DG]"))base=base.substring(0,2);try{for(JourneyData.RailLine line:MetroData.lines(activity,city))if(line.id.equalsIgnoreCase(base))return line.id;}catch(Exception ignored){}return "";}
 private void detail(final CatalogStore.Item item){
  if(closed)return;try{((InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);}catch(Exception ignored){}
  if(detailDialog!=null)detailDialog.dismiss();final Dialog d=dialog(item.name);detailDialog=d;final LinearLayout content=(LinearLayout)d.findViewById(7301);TextView identity=text(item.code+" · "+item.type,14,BLUE);content.addView(identity);
  final String rail=railCode(item);boolean busLine=item.kind==0&&(city==0||city==1||city==2)&&item.type.toLowerCase(new Locale("tr","TR")).contains("otob");
  if(liveStop(item)||busLine||rail.length()>0){Button primary=button(rail.length()>0?"Metro haritasında aç":item.kind==0?"Hat takibini aç":"Canlı takibe geç",true,new View.OnClickListener(){public void onClick(View v){d.dismiss();if(rail.length()>0)navigation.rail(rail);else navigation.track(item);}});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(44));lp.topMargin=dp(12);content.addView(primary,lp);}
  if(item.kind==1&&item.hasPosition()){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(44));lp.topMargin=dp(8);content.addView(button("Haritada göster",false,new View.OnClickListener(){public void onClick(View v){d.dismiss();navigation.point(item);}}),lp);}
  LinearLayout actions=new LinearLayout(activity);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(52));ap.topMargin=dp(8);content.addView(actions,ap);final Button save=button(store.saved(item)?"Kaydedildi":"Kaydet",false,null);save.setOnClickListener(new View.OnClickListener(){public void onClick(View v){toggle(item);save.setText(store.saved(item)?"Kaydedildi":"Kaydet");}});LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,dp(44),1);half.rightMargin=dp(8);actions.addView(save,half);actions.addView(button("Kaynak",false,new View.OnClickListener(){public void onClick(View v){source(item);}}),new LinearLayout.LayoutParams(0,dp(44),1));
  final FrameLayout detail=new FrameLayout(activity);content.addView(detail,new LinearLayout.LayoutParams(-1,dp(compact?150:250)));detail.addView(text("Ayrıntılar yükleniyor…",13,MUTED));show(d);
  worker.execute(new Runnable(){public void run(){try{final ArrayList<CatalogStore.Item> stops=item.kind==0?store.routeStops(item.id):new ArrayList<CatalogStore.Item>();final String schedule=item.kind==1?store.schedule(item.id):"";main.post(new Runnable(){public void run(){if(closed||detailDialog!=d)return;detail.removeAllViews();if(!stops.isEmpty()){LinearLayout stack=new LinearLayout(activity);stack.setOrientation(1);stack.addView(text(stops.size()+" durak · kayıtlı hat dizisi",12,MUTED));ListView list=new ListView(activity);list.setCacheColorHint(palette.surface);list.setDivider(new ColorDrawable(palette.rule));list.setDividerHeight(dp(1));list.setAdapter(new Rows(stops));stack.addView(list,new LinearLayout.LayoutParams(-1,0,1));detail.addView(stack);list.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> p,View view,int position,long id){d.dismiss();detail(stops.get(position));}});}else{ScrollView scroll=new ScrollView(activity);TextView copy=text(item.kind==0?"Bu hat için yerel durak dizisi bulunmuyor.":(item.hasPosition()?"":"Bu durakta koordinat verisi yok.\n\n")+schedule,14,MUTED);scroll.addView(copy);detail.addView(scroll);}}});}catch(Exception e){main.post(new Runnable(){public void run(){if(closed||detailDialog!=d)return;detail.removeAllViews();detail.addView(text("Ayrıntılar şu an okunamadı.",14,MUTED));}});}}});
 }
 private void source(final CatalogStore.Item item){worker.execute(new Runnable(){public void run(){try{final String value=store.source(item.source);main.post(new Runnable(){public void run(){if(closed)return;Dialog d=dialog("Veri kaynağı");LinearLayout content=(LinearLayout)d.findViewById(7301);ScrollView scroll=new ScrollView(activity);scroll.addView(text(value,13,MUTED));content.addView(scroll,new LinearLayout.LayoutParams(-1,dp(compact?210:300)));show(d);}});}catch(Exception ignored){}}});}
 private void nearMenu(){final Dialog d=dialog("Yakındaki duraklar");LinearLayout content=(LinearLayout)d.findViewById(7301);content.addView(text("Seçili şehirde 2 km içindeki katalog durakları. Konum cihazda işlenir.",14,MUTED));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(44));p.topMargin=dp(12);content.addView(button("Cihaz konumunu kullan",true,new View.OnClickListener(){public void onClick(View v){d.dismiss();gps();}}),p);LinearLayout.LayoutParams second=new LinearLayout.LayoutParams(-1,dp(44));second.topMargin=dp(8);content.addView(button("Koordinat gir",false,new View.OnClickListener(){public void onClick(View v){d.dismiss();coordinates();}}),second);show(d);}
 private void coordinates(){final Dialog d=dialog("Konum gir");LinearLayout content=(LinearLayout)d.findViewById(7301);content.addView(text("Enlem",12,MUTED));final EditText latitude=new EditText(activity);latitude.setTextSize(14);latitude.setSingleLine(true);latitude.setInputType(12290);content.addView(latitude,new LinearLayout.LayoutParams(-1,dp(44)));content.addView(text("Boylam",12,MUTED));final EditText longitude=new EditText(activity);longitude.setTextSize(14);longitude.setSingleLine(true);longitude.setInputType(12290);content.addView(longitude,new LinearLayout.LayoutParams(-1,dp(44)));content.addView(button("Durakları bul",true,new View.OnClickListener(){public void onClick(View v){try{double lat=Double.parseDouble(latitude.getText().toString().replace(',','.')),lon=Double.parseDouble(longitude.getText().toString().replace(',','.'));if(Double.isNaN(lat)||Double.isNaN(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new NumberFormatException();d.dismiss();nearby(lat,lon);}catch(Exception e){Toast.makeText(activity,"Geçerli enlem ve boylam gir",Toast.LENGTH_SHORT).show();}}}),new LinearLayout.LayoutParams(-1,dp(44)));show(d);}
 private void nearby(double lat,double lon){state.nearby=true;state.lat=lat;state.lon=lon;state.mode=1;load(true);}
 private void gps(){
  if(Build.VERSION.SDK_INT>=23)try{int fine=((Integer)activity.getClass().getMethod("checkSelfPermission",String.class).invoke(activity,"android.permission.ACCESS_FINE_LOCATION")).intValue(),coarse=((Integer)activity.getClass().getMethod("checkSelfPermission",String.class).invoke(activity,"android.permission.ACCESS_COARSE_LOCATION")).intValue();if(fine!=0&&coarse!=0){activity.getClass().getMethod("requestPermissions",String[].class,Integer.TYPE).invoke(activity,new Object[]{new String[]{"android.permission.ACCESS_FINE_LOCATION","android.permission.ACCESS_COARSE_LOCATION"},Integer.valueOf(7)});Toast.makeText(activity,"İzin verdikten sonra Yakınımda'ya tekrar dokun.",Toast.LENGTH_LONG).show();return;}}catch(Exception e){Toast.makeText(activity,"Konum iznini ayarlardan aç.",Toast.LENGTH_LONG).show();return;}
  pause();locationManager=(LocationManager)activity.getSystemService(Context.LOCATION_SERVICE);try{Location best=null;for(String provider:locationManager.getProviders(true)){Location value=locationManager.getLastKnownLocation(provider);if(value!=null&&System.currentTimeMillis()-value.getTime()<120000&&(best==null||value.getTime()>best.getTime()))best=value;}if(best!=null){nearby(best.getLatitude(),best.getLongitude());return;}locationListener=new LocationListener(){public void onLocationChanged(Location location){pause();if(!closed)nearby(location.getLatitude(),location.getLongitude());}public void onProviderEnabled(String provider){}public void onProviderDisabled(String provider){}public void onStatusChanged(String provider,int status,Bundle extras){}};String provider=locationManager.isProviderEnabled(LocationManager.GPS_PROVIDER)?LocationManager.GPS_PROVIDER:LocationManager.NETWORK_PROVIDER;locationManager.requestLocationUpdates(provider,1000,0,locationListener);range.setText("Konum bekleniyor…");main.postDelayed(new Runnable(){public void run(){if(locationListener!=null){pause();range.setText("Konum alınamadı. Koordinat girebilirsin.");}}},20000);}catch(Exception e){pause();range.setText("Konum kullanılamıyor. Koordinat girebilirsin.");}
 }
 public void pause(){if(locationListener!=null){try{locationManager.removeUpdates(locationListener);}catch(Exception ignored){}locationListener=null;}}
 public void close(){closed=true;generation++;pause();if(detailDialog!=null)detailDialog.dismiss();main.removeCallbacksAndMessages(null);worker.execute(new Runnable(){public void run(){store.close();}});worker.shutdown();}
}
